```python
import os
import csv


def count_log_levels(paths):
    results = []
    for path in paths:
        counts = {"ERROR": 0, "WARN": 0, "INFO": 0}
        try:
            with open(path) as f:
                lines = [line.strip() for line in f]
                for i, line in enumerate(lines):
                    parts = line.split(" ", 3)
                    if len(parts) >= 4 and parts[2] in counts:
                        counts[parts[2]] += 1
        except (FileNotFoundError, PermissionError):
            pass

        results.append({
            "dosya": path.replace("\\", "/"),
            "error": counts["ERROR"],
            "warn": counts["WARN"],
            "info": counts["INFO"]
        })

    # Sort by error descending, then filename ascending
    results.sort(key=lambda x: (-x["error"], x["dosya"]))
    return results


def write_csv(filename, data):
    with open(filename, newline="", encoding="utf-8") as csvfile:
        writer = csv.DictWriter(csvfile, fieldnames=["dosya", "error", "warn", "info"])
        writer.writeheader()
        writer.writerows(data)


def main():
    # We'll assume the script is run in a directory that has 'loglar/' subdirectory
    root = os.path.abspath(".")
    logdir = os.path.join(root, "loglar")

    if not os.path.exists(logdir):
        return

    logfiles = []
    for root_path, dirs, files in os.walk(logdir):
        for filename in files:
            # Only strictly .log extensions; avoid rotated/old logs like log.1 or old.gz
            if filename.endswith(".log") and len(filename.split('.')) == 2:
                full_path = os.path.join(root_path, filename)
                rel_path = os.path.relpath(full_path, root).replace("\\", "/")
                logfiles.append((rel_path, full_path))

    results = []
    for rel_path, full_path in logfiles:
        counts = {"ERROR": 0, "WARN": 0, "INFO": 0}
        try:
            with open(full_path) as f:
                lines = [line.strip() for line in f]
                for i, line in enumerate(lines):
                    parts = line.split(" ", 3)
                    if len(parts) >= 4 and parts[2] in counts:
                        counts[parts[2]] += 1
        except (FileNotFoundError, PermissionError):
            pass

        results.append({
            "dosya": rel_path,
            "error": counts["ERROR"],
            "warn": counts["WARN"],
            "info": counts["INFO"]
        })

    # Sort by error descending, then filename ascending
    results.sort(key=lambda x: (-x["error"], x["dosya"]))
    write_csv("rapor.csv", results)


if __name__ == "__main__":
    main()
```

